"""Build reviewed static public pages and Next route data. No identity/customer data."""
from pathlib import Path
import html, json, shutil, re
root=Path(__file__).resolve().parent
categories=[
 ('2-wheeler','2-wheeler-detailing','2 Wheeler detailing','Care for the details that make your motorcycle yours. Talk to the team about cleaning, finishing and protection for your two-wheeler.'),
 ('hatchback','hatchback-detailing','Hatchback detailing','A fresh cabin and a considered exterior finish for the car that takes you through every day.'),
 ('sedan','sedan-detailing','Sedan detailing','Interior cleaning, exterior care and protection options for your daily drive. Find a package that fits your vehicle and its condition.'),
 ('suv','suv-detailing','SUV detailing','From the school run to the weekend away, give your SUV’s cabin and exterior the attention they deserve.'),
 ('pickup','pickup-detailing','Pickup detailing','Care for a working truck or a weekend companion. Discuss interior cleaning, exterior detailing and protection with the team.'),
 ('van','van-detailing','Van detailing','Detailing for the space you rely on. Talk to us about the size, use and condition of your van to find the right care.'),
 ('ceramic','ceramic-coating','Ceramic coating','Explore a coating finish that brings gloss and water repellency. The team will explain preparation, maintenance and suitable coating options.'),
 ('ppf','ppf','Paint protection film','A clear film layer for the painted surfaces you want to protect. Discuss coverage, preparation and finish with Dapper.'),
 ('aircraft','aircraft-detailing','Aircraft detailing','Specialist attention for aircraft interiors and exteriors. Contact the team to discuss your aircraft, its surfaces and the scope of work.'),
 ('boat','boat-detailing','Boat detailing','Interior and exterior care for your time on the water. Tell us about your boat and its condition for a suitable service recommendation.')]
def esc(s):return html.escape(s,quote=True)
def navigation(active=''):
 links=[('/','Home'),('/services/','Services'),('/portfolio/','Portfolio'),('/about-us/','About Us'),('/contact-us/','Contact Us'),('/account','Account')]
 return '<header class="header"><a class="brand" href="/" aria-label="Dapper Detailing Pros home"><img src="/site/assets/logo.webp" width="44" height="44" alt=""><span>DAPPER<small>DETAILING PROS</small></span></a><nav id="site-navigation" aria-label="Main navigation">'+''.join(f'<a href="{u}"'+(' aria-current="page"' if active==u else '')+f'>{t}</a>' for u,t in links)+'</nav><a class="booking-link" href="/book-appointment/">Book an appointment <span aria-hidden="true">↗</span></a><button class="menu-toggle" hidden aria-controls="site-navigation" aria-expanded="false">Menu</button></header>'
def footer():return '<footer><a class="brand" href="/">DAPPER<small>DETAILING PROS</small></a><p>660 The Kingsway, Peterborough, ON K9J 7C8</p><a href="tel:+17059776217">(705) 977-6217</a><a href="mailto:info@dapperdetailing.ca">info@dapperdetailing.ca</a><p>© 2026 Dapper Detailing Pros Ltd.</p></footer>'
def layout(title,description,body,active=''):
 return '<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#080a0d"><title>'+esc(title)+' | Dapper Detailing Pros</title><meta name="description" content="'+esc(description)+'"><link rel="icon" href="/site/assets/favicon.webp"><link rel="preload" href="/site/assets/manrope-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/site/pages.css"><script src="/site/public-site.js" defer></script><script src="/site/public-data.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'+navigation(active)+'<main id="main" tabindex="-1">'+body+'</main>'+footer()+'<dialog id="portfolio-dialog" aria-labelledby="image-title"><button class="close-image" aria-label="Close image">Close</button><img id="full-image" alt=""><h2 id="image-title"></h2></dialog></body></html>'
def cta():return '<section class="closing"><h2>Your vehicle.<br><span>Our next conversation.</span></h2><a class="button" href="/book-appointment/">Find your next appointment ↗</a><a href="/contact-us/">Talk to the team ↗</a></section>'
pages={}
rows=''.join(f'<a class="service-row" href="/{slug}/"><h2>{esc(title)}</h2><p>{esc(desc)}</p><span aria-hidden="true">↗</span></a>' for key,slug,title,desc in categories)
pages['services']=layout('Services','Explore vehicle detailing, ceramic coating and PPF in Peterborough.','<section class="page-intro"><h1>Care for every<br><span>kind of journey.</span></h1><p>Find your vehicle. Explore the care. Choose your next step with Dapper.</p></section><div class="service-directory">'+rows+'</div>'+cta(),'/services/')
for key,slug,title,desc in categories:
 menu=''.join(f'<a href="/{s}/"'+(' aria-current="page"' if k==key else '')+f'>{esc(t)}</a>' for k,s,t,d in categories)
 body=f'<section class="page-intro service-intro"><div><a class="back-link" href="/services/">← All services</a><h1>{esc(title)}</h1><p>{esc(desc)}</p><a class="button" href="/book-appointment/">Find an appointment ↗</a></div><figure><img src="/site/assets/hero.webp" width="1100" height="825" alt="Inside Dapper’s detailing studio"><figcaption>The Dapper studio, Peterborough.</figcaption></figure></section><section class="service-layout"><nav class="category-navigation" aria-label="Service categories">{menu}</nav><div><h2>Find your care.</h2><p>Available packages are published by the Dapper team. Sign in to see services, pricing and available times for your own vehicle.</p><div data-service-list data-category="{key}" aria-live="polite"><p>Loading packages…</p></div><noscript><p>Contact Dapper for current packages, or sign in to your account.</p></noscript><a class="text-link" href="/account">Sign in to your account ↗</a></div></section>'+cta()
 pages[slug]=layout(title,desc,body,'/services/')
pages['portfolio']=layout('Portfolio','Explore Dapper’s vehicle detailing portfolio.','<section class="page-intro"><h1>Seen in the studio.<br><span>Made for the road.</span></h1><p>Explore the vehicles and finishes cared for by Dapper, published by the team from the studio.</p></section><section class="latest-work"><h2>Work worth a closer look.</h2><div class="filter-bar" role="group" aria-label="Filter portfolio"><button data-filter="all" aria-pressed="true">All</button><button data-filter="detailing" aria-pressed="false">Detailing</button><button data-filter="ceramic" aria-pressed="false">Ceramic coating</button><button data-filter="ppf" aria-pressed="false">PPF</button></div><p id="portfolio-status" role="status">Loading the portfolio…</p><div id="published-portfolio" class="portfolio-grid"></div><noscript><p>Enable JavaScript to view the published gallery, or contact the team about recent work.</p></noscript></section>'+cta(),'/portfolio/')
timeline=[('2022','The beginning','Ayush began detailing alongside his studies in Canada, building the business through mobile work and referrals.'),('2023','Building the foundation','Mohan Preet Singh Virk joined, bringing technology and digital systems into the business.'),('2024','Reaching more drivers','The business invested in its digital presence and reached more vehicle owners around Peterborough.'),('2025','Growing commercial relationships','Dapper expanded its work with dealerships and commercial clients.'),('2026','A home for Dapper','The first shop opened at 660 The Kingsway in Peterborough, alongside mobile detailing services.')]
pages['about-us']=layout('About Us','Meet the people and story behind Dapper Detailing Pros.','<section class="page-intro service-intro"><div><h1>Good people.<br><span>Considered care.</span></h1><p>Built by two childhood friends, Dapper grew from a mobile detailing business into a dedicated Peterborough studio. The care behind every vehicle remains the same.</p></div><figure><img src="/site/assets/hero.webp" width="1100" height="825" alt="The Dapper detailing studio"><figcaption>660 The Kingsway, Peterborough.</figcaption></figure></section><section class="story"><h2>A journey<br>worth caring about.</h2><ol>'+''.join(f'<li><time>{y}</time><div><h3>{t}</h3><p>{d}</p></div></li>' for y,t,d in timeline)+'</ol></section><section class="leadership"><h2>The people behind Dapper.</h2><div><h3>Ayush Kumar Singh</h3><p>CEO</p></div><div><h3>Mohan Preet Singh Virk</h3><p>CTO</p></div></section>'+cta(),'/about-us/')
pages['contact-us']=layout('Contact Us','Contact Dapper Detailing Pros at 660 The Kingsway, Peterborough.','<section class="page-intro"><h1>Let’s talk<br><span>about your vehicle.</span></h1><p>Ready to book, exploring a package, or looking for a custom quote? The Dapper team can help you choose your next step.</p></section><section class="contact-layout"><address><div><h2>Call the studio</h2><a href="tel:+17059776217">(705) 977-6217 ↗</a></div><div><h2>Email the team</h2><a href="mailto:info@dapperdetailing.ca">info@dapperdetailing.ca ↗</a></div><div><h2>Visit us</h2><p>660 The Kingsway<br>Peterborough, ON K9J 7C8<br>Canada</p><a href="https://www.google.com/maps/search/?api=1&amp;query=660+The+Kingsway+Peterborough+ON+K9J+7C8" target="_blank" rel="noopener noreferrer">Get directions ↗</a></div><div><h2>Opening hours</h2><p>8:00 AM–9:00 PM<br>Seven days a week</p><small>Contact us to confirm holiday hours and appointment availability.</small></div></address><figure><img src="/site/assets/hero.webp" width="1100" height="825" alt="Inside Dapper’s Peterborough studio"><figcaption>We look forward to welcoming you.</figcaption></figure></section>'+cta(),'/contact-us/')
# Home remains a complete, isolated document so its cinematic CSS never leaks into dashboards.
home=(root/'index.html').read_text(encoding='utf-8')
home=home.replace('href="assets/','href="/site/assets/').replace('src="assets/','src="/site/assets/').replace('href="studio.css"','href="/site/studio.css"').replace('src="public-site.js"','src="/site/public-site.js"').replace('src="public-data.js"','src="/site/public-data.js"').replace('src="studio-loader.js"','src="/site/studio-loader.js"').replace('src="quote.js"','src="/site/quote.js"').replace('src="story.js"','src="/site/story.js"').replace('src="home-motion.js"','src="/site/home-motion.js"').replace('src="home-scene.js"','src="/site/home-scene.js"').replace('src="home-stage.js"','src="/site/home-stage.js"').replace('"./assets/','"/site/assets/')
studio=(root/'studio.html').read_text(encoding='utf-8')
studio=studio.replace('href="assets/','href="/site/assets/').replace('src="assets/','src="/site/assets/').replace('href="studio.css"','href="/site/studio.css"').replace('src="public-site.js"','src="/site/public-site.js"').replace('src="public-data.js"','src="/site/public-data.js"').replace('src="studio-loader.js"','src="/site/studio-loader.js"').replace('src="quote.js"','src="/site/quote.js"').replace('src="story.js"','src="/site/story.js"').replace('"./assets/','"/site/assets/')
pages['studio']=studio
def metadata(document,path):
 title=html.unescape(re.search(r'<title>(.*?)</title>',document).group(1))
 description=html.unescape(re.search(r'<meta name="description" content="([^"]*)"',document).group(1))
 url='https://dapperdetailing.ca'+path
 tags=f'<link rel="canonical" href="{esc(url)}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{esc(url)}"><meta property="og:image" content="https://dapperdetailing.ca/site/assets/hero.webp"><meta name="twitter:card" content="summary_large_image">'
 return document.replace('</head>',tags+'</head>')
home=metadata(home,'/')
pages={slug:metadata(document,'/'+slug+'/') for slug,document in pages.items()}
directory=root/'pages';directory.mkdir(exist_ok=True)
for slug,body in pages.items():(directory/(slug+'.html')).write_text(body,encoding='utf-8')
(root/'pages.generated.ts').write_text('// Generated by build-pages.py. Public content only.\nexport const homeHTML = '+json.dumps(home,ensure_ascii=False)+';\nexport const publicPages: Record<string,string> = '+json.dumps(pages,ensure_ascii=False)+';\n',encoding='utf-8')
target=root.parent/'dapper-platform/apps/web/public/site';target.mkdir(parents=True,exist_ok=True)
shutil.copytree(root/'assets',target/'assets',dirs_exist_ok=True,ignore=shutil.ignore_patterns('portfolio'))
for file in ['studio.css','studio-ui.js','studio-scene.js','studio-motion.js','studio-loader.js','public-site.js','public-data.js','pages.css','quote.js','story.js','home-motion.js','home-scene.js','home-stage.js','home-frames.js']:shutil.copy2(root/file,target/file)
# The reviewed source archive is served only by the authorized Go content API.
(root/'verification/page-manifest.json').write_text(json.dumps({'routes':['/']+['/'+k+'/' for k in pages]+['/account','/my-bookings/','/booking','/book-appointment/'],'source':'Live public-site structure reviewed 2026-10-23; no legacy pricing or booking defaults imported.'},indent=2)+'\n')
print('Built homepage +',len(pages),'public pages and copied licensed runtime assets.')
